CREATE OR REPLACE FUNCTION public.lab_grupo_exibicao(s text) RETURNS text LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SET search_path=public AS $$ DECLARE chave text:=public.dre_feegow_normalizar_nome(s); BEGIN RETURN CASE chave WHEN '' THEN 'Não informado' WHEN 'nao informado' THEN 'Não informado' WHEN 'nao classificado' THEN 'Não informado' WHEN 'sem grupo' THEN 'Não informado' WHEN 'psquiatria' THEN 'Psiquiatria' WHEN 'psiquiatria' THEN 'Psiquiatria' WHEN 'reumatologia' THEN 'Reumatologia' WHEN 'nutricao' THEN 'Nutrição' WHEN 'usg' THEN 'USG' ELSE initcap(btrim(s)) END; END; $$;
CREATE INDEX IF NOT EXISTS lab_producao_grupo_codigo_nome_idx ON public.lab_producao_feegow(grupo_id,grupo_nome) WHERE grupo_id>0 AND nullif(btrim(grupo_nome),'') IS NOT NULL;